<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ApiError,get,patch,post } from '../api'
const route=useRoute(),router=useRouter(),editing=Boolean(route.params.id),clients=ref<any[]>([]),employees=ref<any[]>([]),saving=ref(false),loading=ref(true),error=ref('')
const form=ref<any>({name:'',clientId:'',ownerId:'',status:'ACTIVE',businessYear:new Date().getFullYear(),services:[],projectNo:'',startDate:'',plannedEndDate:'',actualEndDate:'',targetAmount:undefined,note:''})
const labels:Record<string,string>={BIDDING:'招标代理',COST:'造价/预结算',SUPERVISION:'监理',OTHER:'其他'}
async function load(){loading.value=true;error.value='';try{[clients.value,employees.value]=await Promise.all([get<any[]>('/settings/clients'),get<any[]>('/settings/employees')]);if(editing){const project=await get<any>(`/projects/${route.params.id}`);form.value={...form.value,...project,services:project.services.map((s:any)=>({serviceType:s.serviceType,stage:s.stage,ownerId:s.ownerId,otherDescription:s.otherDescription||''}))}}}catch(e){error.value=e instanceof ApiError?e.message:'表单加载失败'}finally{loading.value=false}}
function toggle(type:string){const index=form.value.services.findIndex((s:any)=>s.serviceType===type);if(index>=0)form.value.services.splice(index,1);else form.value.services.push({serviceType:type,stage:'待开始',ownerId:form.value.ownerId||'',otherDescription:''})}
async function save(){error.value='';if(!form.value.name||!form.value.clientId||!form.value.ownerId||!form.value.services.length){error.value='请填写项目名称、客户、服务类型、负责人和状态。';return}const payload={name:form.value.name,clientId:form.value.clientId,ownerId:form.value.ownerId,status:form.value.status,businessYear:Number(form.value.businessYear),services:form.value.services.map((s:any)=>({serviceType:s.serviceType,stage:s.stage||'待开始',ownerId:s.ownerId||form.value.ownerId,otherDescription:s.otherDescription||undefined})),projectNo:form.value.projectNo||undefined,startDate:form.value.startDate||undefined,plannedEndDate:form.value.plannedEndDate||undefined,actualEndDate:form.value.actualEndDate||undefined,targetAmount:form.value.targetAmount===''||form.value.targetAmount==null?undefined:Number(form.value.targetAmount),note:form.value.note||undefined};saving.value=true;try{const project=editing?await patch<any>(`/projects/${route.params.id}`,payload):await post<any>('/projects',payload);router.push(`/projects/${project.id}`)}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
onMounted(load)
</script>
<template><div v-if="loading" class="empty">正在加载项目表单…</div><div v-else-if="error&&!clients.length" class="empty"><p class="error">{{error}}</p><button class="button secondary" @click="load">重试</button></div><div v-else class="form-layout"><aside><h1 class="title">{{editing?'编辑项目':'新建项目'}}</h1><p class="subtitle">先建立项目的核心事实；所有数据都仅归属于当前账户。</p></aside><form @submit.prevent="save"><div class="form-grid"><div class="field-group full"><label>项目名称 *</label><input v-model.trim="form.name" class="input" maxlength="240" required/></div><div class="field-group"><label>客户 *</label><select v-model="form.clientId" class="select" required><option value="">请选择客户</option><option v-for="x in clients" :key="x.id" :value="x.id">{{x.name}}</option></select></div><div class="field-group"><label>负责人 *</label><select v-model="form.ownerId" class="select" required><option value="">请选择负责人</option><option v-for="x in employees.filter((x:any)=>x.active)" :key="x.id" :value="x.id">{{x.name}}</option></select></div><div class="field-group full"><label>服务类型 *</label><div class="service-chips"><button v-for="(label,type) in labels" :key="type" type="button" class="chip" :class="{active:form.services.some((s:any)=>s.serviceType===type)}" @click="toggle(String(type))">{{label}}</button></div></div><template v-for="s in form.services" :key="s.serviceType"><div class="field-group"><label>{{labels[s.serviceType]}}阶段 *</label><input v-model.trim="s.stage" class="input" required/></div><div v-if="s.serviceType==='OTHER'" class="field-group"><label>其他服务说明 *</label><input v-model.trim="s.otherDescription" class="input" required/></div></template><div class="field-group"><label>项目状态 *</label><select v-model="form.status" class="select"><option value="ACTIVE">在办</option><option value="COMPLETED">已完成</option><option value="CANCELLED">已取消</option></select></div><div class="field-group"><label>业务年份</label><input v-model.number="form.businessYear" class="input" type="number" min="2000" max="2100" required/></div></div><section class="form-section"><h2 class="section-title">更多信息</h2><div class="form-grid"><div class="field-group"><label>内部项目编号</label><input v-model.trim="form.projectNo" class="input" maxlength="100"/></div><div class="field-group"><label>委托/开始日期</label><input v-model="form.startDate" class="input" type="date"/></div><div class="field-group"><label>计划完成日期</label><input v-model="form.plannedEndDate" class="input" type="date"/></div><div class="field-group"><label>项目/采购标的金额</label><input v-model.number="form.targetAmount" class="input" type="number" min="0" step="0.01"/></div><div class="field-group full"><label>备注</label><textarea v-model="form.note" class="textarea" rows="3" maxlength="4000"/></div></div></section><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button type="button" class="button secondary" @click="router.back()">取消</button><button class="button primary" :disabled="saving">{{saving?'保存中…':editing?'保存修改':'创建项目 →'}}</button></div></form></div></template>
